(function () {
"use strict";
var A = window.NR_ASSIST, C = window.NR_CONFIG;
if (!A || !C || document.querySelector(".assist-open")) return;
var B = C.business, esc = A.esc, store = A.store, track = A.track, endpoint = A.endpoint;
var $ = function (s, r) { return (r || document).querySelector(s); };
var ASSIST_KEY = "nr-assist-v1", ASSIST_SEND = 16, ASSIST_CHARS = 9000;
function assistSend(history) {
var send = history.slice(-ASSIST_SEND), total = 0;
send.forEach(function (m) { total += m.content.length; });
while (send.length > 1 && (send[0].role !== "user" || total > ASSIST_CHARS)) total -= send.shift().content.length;
return send;
}
function assistHistory(h) {
if (!Array.isArray(h)) return [];
for (var i = 0; i < h.length; i++) {
if (!h[i] || h[i].role !== (i % 2 ? "assistant" : "user") || typeof h[i].content !== "string") return [];
}
return h.length % 2 ? h.slice(0, -1) : h;
}
function assistLinks(text) {
var site = String(C.siteUrl || "").replace(/\/+$/, "");
return esc(text).replace(/https?:\/\/[^\s<]+/g, function (u) {
var tail = (u.match(/[.,;:!?)]+$/) || [""])[0], url = tail ? u.slice(0, -tail.length) : u;
var raw = url.replace(/&amp;/g, "&");
if (!site || !(raw === site || raw.indexOf(site + "/") === 0)) return url + tail;
var page = raw.slice(site.length).split(/[?#]/)[0] || "/";
var label = page === "/book/" ? "Open the booking form" : site.replace(/^https?:\/\//, "") + page;
return '<a href="' + url + '">' + esc(label) + "</a>" + tail;
}).replace(new RegExp(esc(B.email).replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g"), '<a href="mailto:' + esc(B.email) + '">' + esc(B.email) + "</a>")
.replace(/\n/g, "<br>");
}
var history = assistHistory(store(ASSIST_KEY, undefined, true));
function show() {
var btn = document.createElement("button");
btn.type = "button";
btn.className = "assist-open";
btn.setAttribute("aria-expanded", "false");
btn.setAttribute("aria-controls", "assist-panel");
btn.innerHTML = '<svg class="ic" aria-hidden="true"><use href="#i-chat"/></svg><span class="assist-long">Ask a question</span><span class="assist-short" aria-hidden="true">Ask</span>';
var panel = document.createElement("section");
panel.className = "assist-panel";
panel.id = "assist-panel";
panel.hidden = true;
panel.setAttribute("role", "dialog");
panel.setAttribute("aria-labelledby", "assist-title");
panel.innerHTML = '<div class="assist-head"><p class="assist-title" id="assist-title">Ask a question</p>' +
'<div class="assist-tools"><button type="button" class="assist-new" data-assist-new hidden>New chat</button>' +
'<button type="button" class="assist-close" aria-label="Close"><svg class="ic" aria-hidden="true"><use href="#i-close"/></svg></button></div></div>' +
'<p class="assist-note">An AI assistant that answers from our prices and policies. It can make mistakes: ' + esc(B.ownerFirstName) + " confirms every booking himself. Please don't type personal details here.</p>" +
'<div class="assist-log" role="log" aria-live="polite" data-assist-log></div>' +
'<form class="assist-form" data-assist-form><label class="sr-only" for="assist-input">Your question</label>' +
'<textarea id="assist-input" rows="2" maxlength="1000" placeholder="e.g. How much is a deep clean for a 2-bedroom condo?"></textarea>' +
'<button type="submit" class="btn btn-primary btn-sm">Send</button></form>';
document.body.appendChild(btn);
document.body.appendChild(panel);
var log = $("[data-assist-log]", panel), form = $("[data-assist-form]", panel), input = $("#assist-input"), newBtn = $("[data-assist-new]", panel), busy = false;
function bubble(role, html, cls) {
var p = document.createElement("p");
p.className = "assist-msg assist-" + role + (cls ? " " + cls : "");
p.innerHTML = html;
log.appendChild(p);
log.scrollTop = log.scrollHeight;
return p;
}
var SUGGEST = ((C.assistant && C.assistant.suggestions) || []).filter(function (q) { return typeof q === "string" && q.trim(); }).slice(0, 4);
function chips() {
if (!SUGGEST.length || history.length) return;
var box = document.createElement("div");
box.className = "assist-chips";
box.setAttribute("data-assist-chips", "");
box.setAttribute("role", "group");
box.setAttribute("aria-label", "Suggested questions");
SUGGEST.forEach(function (q) {
var b = document.createElement("button");
b.type = "button";
b.className = "assist-chip";
b.textContent = q;
b.addEventListener("click", function () {
if (busy) return;
input.value = q;
track("assistant_suggestion");
form.requestSubmit ? form.requestSubmit() : form.dispatchEvent(new Event("submit", { cancelable: true }));
});
box.appendChild(b);
});
log.appendChild(box);
}
function greet() {
log.innerHTML = "";
bubble("assistant", "Hi! Ask me about prices, what each clean includes, or whether we clean your area. To book, I'll point you to the form, and " + esc(B.ownerFirstName) + " confirms it personally.");
history.forEach(function (m) { bubble(m.role, m.role === "user" ? esc(m.content) : assistLinks(m.content)); });
chips();
newBtn.hidden = !history.length;
}
greet();
newBtn.addEventListener("click", function () {
if (busy) return;
history = [];
store(ASSIST_KEY, null, true);
greet();
input.focus();
});
function setOpen(open) {
panel.hidden = !open;
btn.setAttribute("aria-expanded", String(open));
btn.classList.toggle("is-open", open);
if (open) { input.focus(); track("assistant_open"); } else btn.focus();
}
btn.addEventListener("click", function () { setOpen(panel.hidden); });
$(".assist-close", panel).addEventListener("click", function () { setOpen(false); });
panel.addEventListener("keydown", function (e) { if (e.key === "Escape") setOpen(false); });
input.addEventListener("keydown", function (e) { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); form.requestSubmit ? form.requestSubmit() : form.dispatchEvent(new Event("submit")); } });
form.addEventListener("submit", function (e) {
e.preventDefault();
var text = input.value.trim();
if (!text || busy) return;
busy = true;
input.value = "";
var sugBox = $("[data-assist-chips]", log);
if (sugBox) sugBox.parentNode.removeChild(sugBox);
history.push({ role: "user", content: text });
bubble("user", esc(text));
var wait = bubble("assistant", "<span class=\"assist-dots\" aria-label=\"Writing an answer\"><span></span><span></span><span></span></span>", "is-waiting");
var send = assistSend(history);
var ctl = window.AbortController ? new AbortController() : null, timer = setTimeout(function () { if (ctl) ctl.abort(); }, 30000);
track("assistant_question");
fetch(endpoint, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ messages: send }), signal: ctl ? ctl.signal : undefined })
.then(function (r) { return r.json().catch(function () { return {}; }).then(function (d) { return { ok: r.ok, d: d }; }); })
.then(function (res) {
if (!res.ok || typeof res.d.reply !== "string") { var e = new Error("failed"); e.say = typeof res.d.error === "string" ? res.d.error : ""; throw e; }
history.push({ role: "assistant", content: res.d.reply });
wait.classList.remove("is-waiting");
wait.innerHTML = assistLinks(res.d.reply);
})
.catch(function (err) {
history.pop();
input.value = text;
wait.classList.remove("is-waiting");
wait.classList.add("is-error");
var msg = err && err.say ? err.say : "Sorry, I can't answer right now. Please try again, or email " + B.email + ".";
wait.innerHTML = assistLinks(msg);
})
.then(function () {
clearTimeout(timer);
busy = false;
if (history.length > ASSIST_SEND) history = history.slice(-ASSIST_SEND);
store(ASSIST_KEY, history, true);
newBtn.hidden = !history.length;
log.scrollTop = log.scrollHeight;
});
});
}
show();
})();
